insert into public.country_occupation_profiles(profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values('AU:special-education-teacher','AU','special-education-teacher','Special Education Teacher','OSCA','2024 v1.0','2514','AUD',true,'State and territory teacher regulatory authorities; AITSL is the migration skills assessing authority for ANZSCO 241511 Special Needs Teacher','https://www.aitsl.edu.au/teach/national-review-of-teacher-registration/framework-for-teacher-registration-in-australia','profile_ready','2026-08-09',now()) on conflict(profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots(profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values('AU:special-education-teacher','2026-05-01',23000,null,null,null,1852,39,86,45,43,57,'2026-05-01',0.59,5.87,12.64,20,0,5,0,13,0,5,10,2,55,'career-opportunity-v1','provisional',jsonb_build_object('current_classification_scope','Current OSCA 251431 Special Education Teacher is a Skill Level 1 occupation teaching students with particular learning difficulties. Specialist Teachers (Vision Impairment) and Teachers of the Deaf are explicitly excluded and classified separately.','legacy_mapping','Current skilled-migration counterpart is ANZSCO 241511 Special Needs Teacher. The aligned JSA six-digit 241511 profile is used for employment and demographic context.','legacy_241511_profile',jsonb_build_object('employment_total',23000,'part_time_share_pct',39,'female_share_pct',86,'median_age',45,'average_full_time_hours',43,'data_as_at','2026-02-01','scope','JSA six-digit legacy ANZSCO 241511 Special Needs Teachers'),'broader_anzsco_2415_context',jsonb_build_object('employment_total',34000,'median_weekly_earnings_aud',2160,'median_hourly_earnings_aud',60,'part_time_share_pct',36,'female_share_pct',85,'median_age',42,'average_full_time_hours',43,'data_as_at','2026-02-01','scope','ANZSCO 2415 Special Education Teachers unit-group context'),'earnings_scope','JSA does not publish six-digit median earnings for ANZSCO 241511. Broader 2415 earnings are context only, so the salary component is zero.','vacancy_scope','May 2026 IVI three-month-average vacancies are 57 at broader ANZSCO 2415, compared with 56.66667 in May 2025, about +0.59% year on year. This broader near-flat movement receives no vacancy trend or intensity credit.','projection_scope','JSA broader ANZSCO 2415 projections are +5.87% from May 2025 to May 2030 and +12.64% to May 2035, receiving partial growth credit.','shortage_note','The reviewed JSA 2025 Occupation Shortage List records current OSCA 251431 as a national shortage occupation. Regional shortage is left null rather than inferred from the national result.','visa_basis','The current skilled occupation instrument lists ANZSCO 241511 Special Needs Teacher with AITSL as assessing authority. Migration assessment and teacher registration are separate processes.','registration_basis','Special Education Teachers working in schools must satisfy state or territory teacher-registration requirements. The exact role can also carry employer or system requirements for specialist preparation.','entry_level_basis','ACU Bachelor of Education (Secondary and Special Education) 0102078 is a four-year course whose graduates are eligible for secondary or special education teacher registration. Flinders Bachelor of Education (Inclusive Education) 117254F is a four-year international route focused on inclusive education.','score_note','Exact aligned employment and demographics are retained, while six-digit salary is unavailable and broader vacancy demand is not scored as exact. National shortage and current AITSL migration evidence receive full credit.'),'2026-08-09') on conflict(profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
